import {ensureDemoDepartures} from './shared/demo-departures.mjs';
import {SYNC_API,POLL_INTERVAL_MS} from './shared/live-config.mjs';
const $b=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=cents=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(cents/100);
const statusText={draft:'Borrador',published:'Publicado',running:'En curso',finished:'Finalizado',cancelled:'Cancelado'};
const payText={credit:'Tarjeta de crédito',debit:'Tarjeta de débito',transfer:'Transferencia bancaria'};
const images={van:'./assets/sprinter.webp',minivan:'./assets/minivan.webp',suv:'./assets/suv.webp',auto:'./assets/sedan.webp'};
const randomToken=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
function save(key,value){localStorage.setItem(key,JSON.stringify(value));}
let catalog=[],catalogReady=false,catalogError='',operatorData=null,operatorBuilt=false,operatorBusy=false,operatorFilter='all',operatorRideId='',editingRide=null,rideRequestId=crypto.randomUUID(),selectedRideId='',showAll=false,checkout=null,checkoutBuilt='',payBusy=false,activeTicket=null,activeTicketToken='',history=[],polling=false,pollTimer=null,operatorRenderKey='',ticketRenderKey='',lastOperatorError='',rideFormOpen=false,profileEditing=false;
let operatorAuth=read('rutasec-operator-access',null),ticketKeys=read('rutasec-ticket-keys',{}),pendingPayment=read('rutasec-pending-checkout',null);
const notify=message=>window.toast?.(message);
async function api(path,{body,token=''}={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(SYNC_API+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal,cache:'no-store',credentials:'omit'});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||'No se pudo sincronizar.'),{status:response.status});return data;}catch(error){if(error.name==='AbortError')throw new Error('El servicio tarda en responder. Reintenta: no se hará un cobro real.');throw error;}finally{clearTimeout(timer);}}
const currentScreen=()=>document.querySelector('.screen.active')?.id;
const getRide=()=>catalog.find(r=>r.id===selectedRideId);
function rememberTicket(id,token){ticketKeys[id]=token;save('rutasec-ticket-keys',ticketKeys);}
function ticketLink(b,token=ticketKeys[b.id]){const u=new URL('./',location.href);u.hash='boleto/'+b.id+'?key='+encodeURIComponent(token||'');return u.href;}
function rideLink(id){const u=new URL('./',location.href);u.hash='salida/'+id;return u.href;}
function ticketWhatsApp(b,token){const i=b.itinerary,link=ticketLink(b,token),text='RESERVA DE DEMOSTRACIÓN · RutasEC\nReserva: '+b.id+'\n'+i.origin+' → '+i.destination+'\nSalida: '+i.date+' · '+i.time+' (Ecuador)\nPasajeros: '+b.passengers.map(p=>p.name).join(', ')+'\nAsientos: '+b.seats+'\nTotal: '+money(b.payment.amountCents)+'\nPago SIMULADO CONFIRMADO · '+payText[b.payment.method]+'\nDetalle de reserva: '+link+'\nAviso preparado manualmente. No existe cobro real.';return 'https://wa.me/'+b.ride.operatorWhatsApp+'?text='+encodeURIComponent(text);}

/* Embarque QR: la reserva y el estado de abordaje se validan siempre contra el servidor. */
const boardingCode=(id,index)=>'RUTASEC-BOARD:'+id+':'+index;
let qrLibraryPromise=null,scannerStream=null,scannerFrame=0,scannerBusy=false;
function qrLibrary(){if(window.QRCode)return Promise.resolve();if(!qrLibraryPromise)qrLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js';script.onload=()=>window.QRCode?resolve():reject(new Error('No se pudo cargar el generador QR.'));script.onerror=()=>reject(new Error('Sin conexión para generar el QR.'));document.head.appendChild(script)});return qrLibraryPromise;}
async function renderBoardingQR(){const b=activeTicket,root=$b('boardingQRs');if(!b||!root)return;root.innerHTML=b.passengers.map((p,i)=>'<div style="padding:14px 0;border-top:1px solid #5554"><strong>'+esc(p.name)+'</strong><p class="market-note">'+(p.boardedAt?'EMBARCADO · QR ya utilizado':'Presenta este QR al subir al vehículo')+'</p><div id="boardingCode'+i+'" style="display:flex;justify-content:center;padding:12px;background:white;width:max-content;margin:8px auto;border-radius:8px"></div></div>').join('');if(b.status!=='confirmed')return;try{await qrLibrary();if(activeTicket?.id!==b.id)return;b.passengers.forEach((p,i)=>{const target=$b('boardingCode'+i);if(target&&!p.boardedAt)new window.QRCode(target,{text:boardingCode(b.id,i),width:208,height:208,correctLevel:window.QRCode.CorrectLevel.M});});}catch(error){root.insertAdjacentHTML('beforeend','<p class="market-note">'+esc(error.message)+'</p>');}}
function ensureBoardingScanner(){if($b('boardingScanner'))return;const div=document.createElement('div');div.id='boardingScanner';div.hidden=true;div.style.cssText='padding:16px 0';div.innerHTML='<h2 class="market-h2">Verificar boleto QR</h2><video id="boardingCamera" playsinline muted autoplay style="width:100%;max-height:300px;background:#111;border-radius:10px"></video><p id="boardingScanState" class="market-note" role="status">Apunta al código QR del pasajero.</p><label class="field">Código manual (alternativa)<input class="form-input" id="boardingManualCode" placeholder="RUTASEC-BOARD:..."></label><div class="market-controls"><button type="button" class="yellow" onclick="BookingApp.validateQR(document.getElementById(&quot;boardingManualCode&quot;).value)">Verificar código</button><button type="button" class="security-outline" onclick="BookingApp.closeScanner()">Cerrar cámara</button></div>';const parent=$b('operatorReservationsTitle');const panel=document.querySelector('.operator-section[data-section="scanner"]');if(panel)panel.appendChild(div);else parent.parentNode.insertBefore(div,parent);}
function closeBoardingScanner(){if(scannerFrame)cancelAnimationFrame(scannerFrame);scannerFrame=0;if(scannerStream){scannerStream.getTracks().forEach(t=>t.stop());scannerStream=null;}const el=$b('boardingScanner');if(el)el.hidden=true;scannerBusy=false;}
async function openBoardingScanner(){ensureBoardingScanner();closeBoardingScanner();$b('boardingScanner').hidden=false;$b('boardingScanState').textContent='Abriendo cámara…';try{if(!('BarcodeDetector'in window))throw new Error('Este navegador no admite lectura QR integrada. Utiliza Chrome en Android o el código manual.');const detector=new BarcodeDetector({formats:['qr_code']});scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$b('boardingCamera');video.srcObject=scannerStream;await video.play();$b('boardingScanState').textContent='Apunta al QR del boleto.';const scan=async()=>{if(!scannerStream)return;try{if(video.readyState>=2&&!scannerBusy){const codes=await detector.detect(video);if(codes.length){await validateBoardingQR(codes[0].rawValue);return;}}}catch(e){$b('boardingScanState').textContent=e.message;}scannerFrame=requestAnimationFrame(scan)};scannerFrame=requestAnimationFrame(scan);}catch(error){$b('boardingScanState').textContent=error.message;}}
async function validateBoardingQR(value){if(scannerBusy)return;scannerBusy=true;const status=$b('boardingScanState');try{const match=String(value||'').trim().match(/^RUTASEC-BOARD:([a-f0-9-]{36}):(\d+)$/i);if(!match)throw new Error('Código QR no reconocido.');const id=match[1],index=Number(match[2]);if(!operatorAuth)throw new Error('Accede primero al panel de la operadora.');const fresh=await api('/api/operator',{token:operatorAuth.token});operatorData=fresh;const b=fresh.bookings.find(b=>b.id===id);if(!b||!Number.isSafeInteger(index)||index<0||index>=b.passengers.length)throw new Error('Boleto no pertenece a esta operadora o pasajero inexistente.');const p=b.passengers[index];if(b.status!=='confirmed'||!['published','running'].includes(b.ride.status))throw new Error('Reserva cancelada o viaje no habilitado para embarque.');if(p.boardedAt)throw new Error(p.name+' ya fue registrado como embarcado.');status.textContent='Verificando '+p.name+' · '+b.itinerary.origin+' → '+b.itinerary.destination+'…';await api('/api/bookings/'+id,{token:operatorAuth.token,body:{action:'board',passengerIndex:index}});closeBoardingScanner();operatorRenderKey='';await refreshOperator();notify('Embarque confirmado: '+p.name);$b('operatorReservationsTitle').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){if(status)status.textContent=error.message;notify(error.message);scannerBusy=false;if(scannerStream){scannerFrame=requestAnimationFrame(async()=>{scannerBusy=false;await openBoardingScanner();});}}}

function syncFleet(){fleet.splice(0,fleet.length,...catalog.filter(r=>r.status==='published').map(r=>({id:r.id,type:r.vehicleType==='minivan'?'van':r.vehicleType,title:r.vehicle,operator:r.operatorName,seats:r.available,capacity:r.capacity,price:r.priceCents/100,time:r.time,arrival:'Por confirmar',img:images[r.vehicleType],ride:r})));if(selectedRideId)selected=Math.max(0,fleet.findIndex(v=>v.id===selectedRideId));}
let catalogLoading=null;
async function loadCatalog(){if(catalogLoading)return catalogLoading;catalogLoading=refreshCatalog();try{return await catalogLoading}finally{catalogLoading=null}}
async function refreshCatalog(){try{let data=await api('/api/catalog');if(['home','results'].includes(currentScreen())&&await ensureDemoDepartures(api,{origin:$b('from').value,destination:$b('to').value,date:$b('date').value},data.rides))data=await api('/api/catalog');const changed=JSON.stringify(data.rides)!==JSON.stringify(catalog);catalog=data.rides;catalogReady=true;catalogError='';syncFleet();if(changed&&currentScreen()==='results')renderResults();if(changed&&currentScreen()==='detail')renderDetail();if(currentScreen()==='booking'&&checkout){const r=getRide();const e=$b('checkoutAvailability');if(e)e.textContent=r?r.available+' asientos disponibles ahora':'La salida ya no está disponible';}}catch(error){catalogError=error.message;if(currentScreen()==='results')renderResults();}}
/* Filtros por empresa y marcas de operadora; las favoritas se guardan por dispositivo. */
let passengerSort='soon',passengerCompany='',favoriteOperators=read('rutasec-favorite-operators',[]);
const brandKey=id=>'rutasec-operator-brand-'+id;
const getLocalBrand=id=>read(brandKey(id),{});
function operatorNameFor(v){return v.ride.operatorName||v.operator||''}
function renderPassengerFilters(){
 const root=$b('rides');if(!root)return;
 let bar=$b('passengerCompanyFilters');
 if(!bar){bar=document.createElement('div');bar.id='passengerCompanyFilters';root.parentNode.insertBefore(bar,root);}
 const companies=[...new Set(fleet.filter(v=>showAll||(v.ride.origin===$b('from').value&&v.ride.destination===$b('to').value&&v.ride.date===$b('date').value)).map(operatorNameFor))].sort((a,b)=>a.localeCompare(b,'es'));
 if(passengerCompany&&!companies.includes(passengerCompany))passengerCompany='';
 bar.innerHTML='<div class="market-controls" style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><button type="button" class="'+(passengerSort==='soon'?'selected':'')+'" onclick="BookingApp.passengerFilter(\'soon\')">Próximas salidas</button><button type="button" class="'+(passengerSort==='company'?'selected':'')+'" onclick="BookingApp.passengerFilter(\'company\')">Por empresa</button><button type="button" class="'+(passengerSort==='favorites'?'selected':'')+'" onclick="BookingApp.passengerFilter(\'favorites\')">Favoritas</button></div>'+
 (passengerSort==='company'?'<label class="field">Filtrar por operadora<select id="passengerCompanySelect" class="form-input" onchange="BookingApp.companyFilter(this.value)"><option value="">Todas las operadoras</option>'+companies.map(name=>'<option value="'+esc(name)+'" '+(passengerCompany===name?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label>':'');
}
function toggleOperatorFavorite(name){favoriteOperators=favoriteOperators.includes(name)?favoriteOperators.filter(n=>n!==name):[...favoriteOperators,name];save('rutasec-favorite-operators',favoriteOperators);renderResults();}
function renderBrandEditor(){
 const panel=document.querySelector('.operator-section[data-section="brand"]');if(!panel||!operatorAuth)return;
 const brand=getLocalBrand(operatorAuth.id);
 const form=panel.querySelector('#operatorBrandForm');if(!form)return;
 for(const field of ['description','cover','logo','photos']){const el=form.elements.namedItem(field);if(el&&document.activeElement!==el)el.value=brand[field]||'';}
 const state=$b('operatorBrandPreview');if(state)state.innerHTML=(brand.cover?'<img src="'+esc(brand.cover)+'" alt="Portada" style="width:100%;max-height:180px;object-fit:cover;border-radius:10px">':'')+'<h3>'+esc(operatorData?.profile?.name||'Mi operadora')+'</h3><p>'+esc(brand.description||'Descripción de la operadora')+'</p>';
}
function saveBrand(){if(!operatorAuth)return;const form=$b('operatorBrandForm');if(!form)return;const data={};for(const field of ['description','cover','logo','photos'])data[field]=String(form.elements.namedItem(field)?.value||'').trim().slice(0,1200);
 for(const field of ['cover','logo'])if(data[field]&&!/^https:\/\//i.test(data[field]))return notify('Utiliza una URL HTTPS para '+field+'.');
 save(brandKey(operatorAuth.id),data);renderBrandEditor();notify('Marca guardada en este dispositivo. La sincronización pública requiere ampliar el servidor.');}
function renderResults(){const root=$b('rides');if(!root)return;renderPassengerFilters();$b('routeTitle').textContent=showAll?'Salidas publicadas':$b('from').value+' → '+$b('to').value;$b('routeMeta').textContent=showAll?'Disponibilidad sincronizada entre teléfonos':formatDate($b('date').value)+' · '+$b('people').value+' pasajero(s)';const note=document.querySelector('#results .demo-note');if(note)note.textContent='Pagos y boletos de demostración. Los cupos y las reservas se sincronizan entre dispositivos.';
 if(!catalogReady&&!catalogError){root.innerHTML='<p class="market-empty">Conectando a las salidas publicadas…</p>';return;}
 const list=fleet.map((v,i)=>({v,i})).filter(({v})=>(showAll||(v.ride.origin===$b('from').value&&v.ride.destination===$b('to').value&&v.ride.date===$b('date').value))&&(activeFilter==='all'||v.type===activeFilter)&&Number($b('people').value)<=v.seats&&(mode!=='private'||v.seats===v.capacity)&&(passengerSort!=='company'||!passengerCompany||operatorNameFor(v)===passengerCompany)&&(passengerSort!=='favorites'||favoriteOperators.includes(operatorNameFor(v)))).sort((a,b)=>a.v.ride.date.localeCompare(b.v.ride.date)||a.v.ride.time.localeCompare(b.v.ride.time));
 root.innerHTML='<div class="market-subhead"><strong>'+list.length+' salida(s) disponibles</strong><span class="market-sync '+(catalogError?'offline':'')+'">'+(catalogError?'Sin conexión':'● Sincronizado')+'</span></div>'+(catalogError?'<p class="market-note bad">'+esc(catalogError)+'</p>':'')+list.map(({v,i})=>'<article class="ride"><div class="ride-main"><img src="'+v.img+'" alt="'+esc(v.title)+'" width="135" height="73"><h3>'+esc(v.operator)+'</h3><button type="button" class="security-link" style="font-size:13px;padding:4px 0" onclick="BookingApp.favoriteOperator(decodeURIComponent(\''+encodeURIComponent(v.operator)+'\'))">'+(favoriteOperators.includes(v.operator)?'♥ Favorita':'♡ Guardar operadora')+'</button><div class="market-badge">PUBLICADO · '+v.seats+' DISPONIBLES</div><div class="detail">'+vehicleIcon+' '+esc(v.title)+'</div><div class="time">'+esc(v.ride.time)+' '+arrowIcon+' '+esc(v.ride.destination)+'</div><div class="market-note">'+esc(v.ride.origin)+' → '+esc(v.ride.destination)+' · '+esc(v.ride.date)+'</div></div><div class="ride-right"><div class="cost">'+money(v.ride.priceCents*(mode==='private'?v.capacity:1))+'<small>'+(mode==='private'?'vehículo completo':'por asiento')+'</small></div><button class="arrow" aria-label="Reservar salida de '+esc(v.operator)+'" onclick="BookingApp.choose('+i+')">'+chevronIcon+'</button></div></article>').join('');
 if(!list.length)root.innerHTML+='<div class="market-empty"><p>No hay salidas publicadas con estos filtros. El operador puede publicar una desde su teléfono y aparecerá aquí automáticamente.</p><button class="security-outline" onclick="BookingApp.allDepartures()">Ver todas las salidas publicadas</button><button class="security-link" onclick="show(\'operator\')">Ir al panel del operador →</button></div>';
}
function choose(index){const item=fleet[index];if(!item)return;selected=index;selectedRideId=item.id;checkout=null;checkoutBuilt='';show('detail');}
function renderDetail(){const r=getRide();if(!r){$b('carTitle').textContent='Salida no disponible';return;}$b('showCar').src=images[r.vehicleType];$b('showCar').alt=r.vehicle;$b('carCategory').textContent=r.vehicleType==='auto'?'AUTO':r.vehicleType==='suv'?'SUV':'FURGONETA';$b('carTitle').textContent=r.vehicle;$b('carOperator').textContent=r.operatorName+' · '+r.origin+' → '+r.destination;$b('carCapacity').textContent=r.available+' asientos disponibles · '+r.occupied+' ocupados';$b('carTime').textContent=r.date+' · Salida '+r.time+' (Ecuador)';$b('carPrice').textContent=money(r.priceCents*(mode==='private'?r.capacity:1))+(mode==='private'?' / vehículo':' / asiento');const btn=document.querySelector('#detail button.yellow');btn.disabled=r.status!=='published'||r.available<Number($b('people').value);btn.textContent='Reservar este viaje →';}
function renderCheckout(){const r=getRide();const root=$b('checkoutBody');if(!r){root.innerHTML='<p class="market-empty">Selecciona una salida publicada para reservar.</p>';return;}const count=Number($b('people').value)||1,seats=mode==='private'?r.capacity:count,signature=r.id+':'+seats+':'+mode+':'+count;if(checkoutBuilt===signature&&$b('checkoutForm'))return;checkoutBuilt=signature;const pending=pendingPayment?.rideId===r.id&&pendingPayment.seats===seats&&pendingPayment.mode===mode?pendingPayment:null;checkout=pending||{rideId:r.id,requestId:crypto.randomUUID(),bookingToken:randomToken(),seats,mode,quotedPriceCents:r.priceCents,passengers:[],paymentMethod:'credit'};
 root.innerHTML='<span class="tag">CHECKOUT FICTICIO</span><h1 class="checkout-title">Confirma tu viaje.</h1><p class="sub">Sin cobro real. No ingreses datos bancarios ni números de tarjeta.</p><div class="checkout-summary"><strong>'+esc(r.origin)+' → '+esc(r.destination)+'</strong>'+esc(r.operatorName)+' · '+esc(r.vehicle)+'<br>'+esc(r.date)+' · '+esc(r.time)+'<br>'+seats+' asiento(s) '+(mode==='private'?'· Vehículo privado':'')+'<p id="checkoutAvailability" class="market-note">'+r.available+' asientos disponibles ahora</p></div><form id="checkoutForm" onsubmit="event.preventDefault();BookingApp.pay()"><h2 class="market-h2">Pasajeros</h2>'+Array.from({length:count},(_,i)=>'<label class="field">Pasajero '+(i+1)+'<input class="form-input passenger-name" aria-label="Nombre del pasajero '+(i+1)+'" required minlength="2" maxlength="80" placeholder="Nombre y apellido de prueba" value="'+esc(checkout.passengers[i]||('Pasajero de demostración '+(i+1)))+'"></label>').join('')+'<h2 class="market-h2">Pago de demostración</h2><div class="payment-methods">'+[['credit','Tarjeta de crédito'],['debit','Tarjeta de débito'],['transfer','Transferencia bancaria']].map(([v,label])=>'<label><input type="radio" name="demoPayment" value="'+v+'" '+(checkout.paymentMethod===v?'checked':'')+'>'+label+'</label>').join('')+'</div><p class="payment-fake">Usamos un medio de pago ficticio. Se registrará como <strong>pago simulado confirmado</strong>; no se procesará ningún cargo.</p><div class="checkout-total"><span>Total simulado</span><strong>'+money(r.priceCents*seats)+'</strong></div><p id="checkoutError" class="checkout-error" role="alert"></p><button id="confirmDemoPayment" class="yellow" style="width:100%">Continuar</button></form>';
}
async function pay(){if(payBusy||!checkout)return;const form=$b('checkoutForm');if(!form.reportValidity())return;payBusy=true;const button=$b('confirmDemoPayment');button.disabled=true;button.textContent='Confirmando reserva…';$b('checkoutError').textContent='';checkout.passengers=Array.from(document.querySelectorAll('.passenger-name'),e=>e.value.trim());checkout.paymentMethod=document.querySelector('[name="demoPayment"]:checked').value;pendingPayment=checkout;save('rutasec-pending-checkout',pendingPayment);try{const result=await api('/api/bookings',{body:checkout});rememberTicket(result.booking.id,checkout.bookingToken);pendingPayment=null;localStorage.removeItem('rutasec-pending-checkout');activeTicket=result.booking;activeTicketToken=checkout.bookingToken;ticketRenderKey='';history.unshift(result.booking);const url=ticketLink(result.booking,checkout.bookingToken);location.hash=new URL(url).hash;show('ticket');renderTicket();await loadCatalog();notify('Pago simulado confirmado. Boleto generado y cupos actualizados.');}catch(error){$b('checkoutError').textContent=error.message;await loadCatalog();if(error.status===409&&/precio cambió/i.test(error.message)){pendingPayment=null;localStorage.removeItem('rutasec-pending-checkout');checkoutBuilt='';renderCheckout();$b('checkoutError').textContent='El precio cambió. Revisa el nuevo total y confirma de nuevo si deseas continuar.';}}finally{payBusy=false;if(button?.isConnected){button.disabled=false;button.textContent='Continuar';}}}
async function loadTicket(id,token){activeTicketToken=token||ticketKeys[id]||'';if(!activeTicketToken){$b('ticketBody').innerHTML='<p class="market-empty">Abre el enlace completo del boleto, que incluye su acceso privado.</p>';return;}try{const data=await api('/api/bookings/'+id,{token:activeTicketToken});activeTicket=data.booking;rememberTicket(id,activeTicketToken);renderTicket();}catch(error){$b('ticketBody').innerHTML='<p class="market-empty">'+esc(error.message)+'</p>';}}
function renderTicket(){if(!activeTicket)return;const b=activeTicket,i=b.itinerary,key=JSON.stringify(b);if(ticketRenderKey===key&&$b('ticketBody').dataset.ticket===b.id)return;ticketRenderKey=key;$b('ticketBody').dataset.ticket=b.id;const confirmed=b.status==='confirmed';$b('ticketBody').innerHTML='<div class="ticket-card"><span class="tag">BOLETO DE DEMOSTRACIÓN</span><h1>'+esc(i.origin)+' → '+esc(i.destination)+'</h1><div class="ticket-id">RESERVA '+esc(b.id)+'</div><dl><dt>SALIDA · ECUADOR</dt><dd>'+esc(i.date)+' · '+esc(i.time)+'</dd><dt>OPERADORA Y VEHÍCULO</dt><dd>'+esc(i.operatorName)+' · '+esc(i.vehicle)+'</dd><dt>ASIENTOS RESERVADOS</dt><dd>'+b.seats+(b.mode==='private'?' · Vehículo completo':'')+'</dd><dt>ESTADO DE LA RESERVA</dt><dd>'+(!confirmed?'Cancelada':b.ride.status==='finished'?'Viaje finalizado':'Confirmada')+'</dd></dl><ol class="ticket-passengers">'+b.passengers.map(p=>'<li>'+esc(p.name)+(p.boardedAt?' · Abordó':'')+'</li>').join('')+'</ol><div class="ticket-paid">'+(confirmed?'✓ PAGO SIMULADO CONFIRMADO':'PAGO SIMULADO REEMBOLSADO')+'<br>'+esc(payText[b.payment.method])+' · '+money(b.payment.amountCents)+'<br><small>Sin cargo bancario real.</small></div></div><h2 class="market-h2">QR de embarque</h2><div id="boardingQRs"></div><div class="ticket-actions">'+(confirmed&&b.ride.liveId?'<button class="yellow" onclick="BookingApp.followTicket()">'+(b.ride.status==='finished'?'Ver recorrido finalizado':'Abrir viaje en curso')+'</button>':confirmed?'<p class="ticket-await">Esperando a que la operadora inicie el viaje. El seguimiento se habilitará automáticamente aquí.</p>':'')+(confirmed&&(b.ride.operatorWhatsApp&&b.ride.operatorWhatsApp!=='00000000')?'<a class="security-outline" id="notifyOperatorWhatsApp" href="'+esc(ticketWhatsApp(b,activeTicketToken))+'" target="_blank" rel="noopener noreferrer">Avisar a la operadora por WhatsApp</a>':'')+'<button class="security-outline" onclick="BookingApp.shareCurrentTicket()">Copiar enlace del boleto</button><button class="security-outline" onclick="window.print()">Imprimir boleto</button>'+(confirmed&&b.ride.status==='published'?'<button class="market-small danger" onclick="BookingApp.cancelCurrent()">Cancelar reserva demo</button>':'')+'</div><p class="market-note">El operador recibe esta reserva en su panel aunque no envíes WhatsApp. El mensaje se prepara; tú confirmas el envío.</p><p class="market-note">El enlace del boleto permite consultar nombres y reserva. Compártelo solo con las personas involucradas en esta demostración.</p>';renderBoardingQR();
}
async function loadHistory(){const items=await Promise.all(Object.entries(ticketKeys).slice(-20).reverse().map(async([id,token])=>{try{return (await api('/api/bookings/'+id,{token})).booking}catch{return null}}));history=items.filter(Boolean);if(currentScreen()==='mytrip')renderHistory();}
function renderHistory(){const root=$b('tripView');root.innerHTML='<p class="market-note">Reservas sincronizadas · pagos de demostración</p>'+(!history.length?'<p>No tienes boletos sincronizados en este teléfono.</p><button class="yellow" onclick="show(\'results\')">Buscar salidas publicadas</button>':history.map(b=>'<article><span class="market-status '+(b.status==='cancelled'?'cancelled':'')+'">'+(b.status==='cancelled'?'CANCELADA':'CONFIRMADA · '+(statusText[b.ride.status]||''))+'</span><h3>'+esc(b.itinerary.origin)+' → '+esc(b.itinerary.destination)+'</h3><p>'+esc(b.itinerary.date)+' · '+esc(b.itinerary.time)+' · '+b.seats+' asiento(s)<br>'+esc(b.itinerary.operatorName)+'<br>'+money(b.payment.amountCents)+' · '+(b.payment.status==='simulated_confirmed'?'Pago simulado confirmado':'Reembolso simulado')+'</p><button class="market-small" onclick="BookingApp.openTicket(\''+b.id+'\')">Ver boleto</button></article>').join(''));
 const legacy=read('rutasec-demo',null);if(legacy)root.innerHTML+='<article><span class="market-badge">RESERVA ANTERIOR · SOLO LOCAL</span><h3>'+esc(legacy.from)+' → '+esc(legacy.to)+'</h3><p>'+esc(legacy.date)+' · '+esc(legacy.time)+'<br>Creada antes de la sincronización; no descuenta cupos del catálogo compartido.</p></article>';
}

/* Navegación independiente para operadoras: preserva los nodos y sus eventos. */
let operatorSection='overview';
function setupOperatorNavigation(){const root=$b('operatorBody'),dashboard=$b('operatorDashboard');if(!root||!dashboard||$b('operatorSubnav'))return;const style=document.createElement('style');style.textContent='.shell[data-screen="operator"] #bottomNav{display:none!important}.operator-subnav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:18px 0}.operator-subnav button{border:1px solid #8885;background:transparent;color:inherit;border-radius:8px;padding:12px 4px;font-size:12px;cursor:pointer}.operator-subnav button.active{background:#e8b83d;color:#161616;border-color:#e8b83d;font-weight:700}.operator-section[hidden]{display:none!important}.operator-section{padding-top:10px}.operator-section .market-h2{margin-top:16px}@media(min-width:650px){.operator-subnav{grid-template-columns:repeat(7,minmax(0,1fr))}}';document.head.appendChild(style);
const nav=document.createElement('nav');nav.id='operatorSubnav';nav.className='operator-subnav';nav.setAttribute('aria-label','Menú de operadora');const sections=[['overview','Resumen'],['rides','Viajes'],['reservations','Reservas'],['payments','Cobros'],['scanner','Escanear QR'],['profile','Perfil'],['brand','Mi marca']];nav.innerHTML=sections.map(([id,label])=>'<button type="button" data-section="'+id+'" onclick="BookingApp.operatorSection(\''+id+'\')">'+label+'</button>').join('');root.insertBefore(nav,dashboard);
const panels={};for(const [id] of sections){const el=document.createElement('section');el.className='operator-section';el.dataset.section=id;el.hidden=true;panels[id]=el;dashboard.appendChild(el);}
const move=(id,ids)=>ids.forEach(name=>{const el=$b(name);if(el)panels[id].appendChild(el)});
move('overview',['operatorTotals']);move('rides',['marketRideForm','operatorFilters','operatorRideList']);move('reservations',['operatorReservationsTitle','operatorReservations']);move('payments',['operatorSalesHistory']);move('scanner',['boardingScanner']);move('profile',['operatorProfileToggle','marketProfileForm']);if(!operatorAuth){root.insertBefore($b('marketProfileForm'),nav);nav.hidden=true;}
const heading=(id,title)=>{const h=document.createElement('h2');h.className='market-h2';h.textContent=title;panels[id].prepend(h)};heading('overview','Resumen de operación');heading('rides','Mis viajes');heading('reservations','Reservas por viaje');heading('payments','Historial de cobros simulados');heading('scanner','Control de embarque');heading('profile','Datos de la operadora');heading('brand','Personalización de marca');panels.brand.insertAdjacentHTML('beforeend','<p class="market-note">Configuración preliminar guardada en este dispositivo. Todavía no se publica a los pasajeros ni se sincroniza con otros teléfonos.</p><form id="operatorBrandForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveBrand()"><label class="field">Descripción comercial<textarea class="form-input" name="description" rows="3" maxlength="1200"></textarea></label><label class="field">URL HTTPS de portada<input class="form-input" name="cover" type="url" placeholder="https://..."></label><label class="field">URL HTTPS del logotipo<input class="form-input" name="logo" type="url" placeholder="https://..."></label><label class="field">Enlaces a fotografías (uno por línea)<textarea class="form-input" name="photos" rows="3"></textarea></label><button class="yellow">Guardar mi marca</button></form><div id="operatorBrandPreview"></div>');
const rideButton=Array.from(dashboard.querySelectorAll('button')).find(b=>b.textContent.trim()==='Crear nuevo viaje');if(rideButton)panels.rides.prepend(rideButton);
const scannerButton=Array.from(dashboard.querySelectorAll('button')).find(b=>b.textContent.trim()==='Escanear boleto QR');if(scannerButton)panels.scanner.appendChild(scannerButton);
const scannerNote=scannerButton?.nextElementSibling;if(scannerNote?.classList.contains('market-note'))panels.scanner.appendChild(scannerNote);
const headings=Array.from(dashboard.children).filter(el=>el.classList.contains('market-h2'));headings.forEach(h=>{if(!h.closest('.operator-section'))h.remove()});
selectOperatorSection(operatorSection);
}
function selectOperatorSection(section){operatorSection=section;const nav=$b('operatorSubnav');if(!nav)return;nav.querySelectorAll('button').forEach(b=>{const active=b.dataset.section===section;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$b('operatorDashboard').querySelectorAll('.operator-section').forEach(p=>p.hidden=p.dataset.section!==section);if(section==='scanner')ensureBoardingScanner();if(section==='brand')renderBrandEditor();}

function operatorSkeleton(){if(operatorBuilt)return;operatorBuilt=true;const option=cities.map(c=>'<option>'+esc(c)+'</option>').join('');$b('operatorBody').innerHTML='<span class="tag">PANEL DE DEMOSTRACIÓN</span><h1 class="page-title">Tu operación, al día.</h1><p class="market-note">Viajes, reservas y pagos simulados compartidos entre teléfonos.</p><button id="operatorProfileToggle" class="security-link" onclick="BookingApp.editOperatorProfile()" hidden>Editar operadora y WhatsApp</button><form id="marketProfileForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveOperator()"><h2>Operadora y WhatsApp</h2><label class="field">Nombre de la operadora<input id="marketOperatorName" class="form-input" minlength="2" maxlength="80" required placeholder="Nombre de tu operadora"></label><label class="field">WhatsApp para recibir avisos de reservas<input id="marketOperatorPhone" class="form-input" type="tel" required placeholder="+593 99 123 4567"></label><button id="saveOperatorProfile" class="yellow">Guardar operadora</button><p id="operatorProfileMessage" class="market-note" role="status">Configura tu operadora y el WhatsApp que recibirá los avisos de sus reservas. Este número se guarda previamente; no se solicita al pasajero durante el pago.</p></form><div id="operatorDashboard" hidden><div id="operatorTotals" class="market-summary"></div><button class="yellow" style="width:100%" onclick="BookingApp.newRide()">Crear nuevo viaje</button><form id="marketRideForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveRide()"><h2 id="rideFormTitle">Crear viaje</h2><div class="market-grid"><label class="field">Origen<select class="form-input" id="marketFrom" required>'+option+'</select></label><label class="field">Destino<select class="form-input" id="marketTo" required>'+option+'</select></label><label class="field">Fecha<input class="form-input" id="marketDate" type="date" required></label><label class="field">Hora<input class="form-input" id="marketTime" type="time" value="08:00" required></label></div><label class="field">Tipo de vehículo<select class="form-input" id="marketVehicleType" onchange="BookingApp.vehiclePreset(this.value)"><option value="van">Furgoneta grande</option><option value="minivan">Furgoneta pequeña</option><option value="suv">SUV</option><option value="auto">Auto sedán</option></select></label><label class="field">Vehículo<input class="form-input" id="marketVehicle" value="Mercedes Sprinter" required maxlength="80"></label><div class="market-grid"><label class="field">Capacidad<input class="form-input" id="marketCapacity" type="number" min="1" max="30" value="8" required></label><label class="field">Precio por asiento · USD<input class="form-input" id="marketPrice" type="number" min="1" max="1000" step="0.01" value="15" required></label></div><label class="market-check" id="marketPublishLabel"><input type="checkbox" id="marketPublish" checked>Publicar para que los pasajeros puedan reservar</label><p id="rideFormError" class="checkout-error" role="alert"></p><button id="saveMarketRide" class="yellow">Publicar viaje</button><button type="button" class="security-link" id="cancelRideEdit" onclick="BookingApp.cancelEdit()" hidden>Cancelar edición</button><p class="market-note">El recorrido simulado está disponible para Cuenca–Guayaquil.</p></form><h2 class="market-h2">Mis viajes</h2><div id="operatorFilters" class="market-controls">'+[['all','Todos'],['published','Publicados'],['upcoming','Próximos'],['running','En curso'],['finished','Finalizados'],['cancelled','Cancelados']].map(([v,t])=>'<button type="button" onclick="BookingApp.filterRides(\''+v+'\')" data-operator-filter="'+v+'" class="'+(v==='all'?'selected':'')+'">'+t+'</button>').join('')+'</div><div id="operatorRideList"></div><h2 class="market-h2">Control de embarque</h2><button type="button" class="yellow" onclick="BookingApp.openScanner()">Escanear boleto QR</button><p class="market-note">Verifica el QR y registra el embarque.</p><h2 class="market-h2" id="operatorReservationsTitle">Reservas por viaje</h2><div id="operatorReservations"></div><h2 class="market-h2">Historial de ventas simuladas</h2><div id="operatorSalesHistory"></div></div><p id="operatorSyncState" class="market-note" role="status"></p>';setupOperatorNavigation();$b('marketFrom').value='Cuenca';$b('marketTo').value='Guayaquil';$b('marketDate').value=$b('date').value;$b('marketDate').min=localDate(new Date());}
async function openOperator(){operatorSkeleton();if(operatorAuth)await refreshOperator();}
async function saveOperator(){operatorSkeleton();const name=$b('marketOperatorName').value.trim(),whatsapp=$b('marketOperatorPhone').value.trim();if(!name||!whatsapp)return;const button=$b('saveOperatorProfile');button.disabled=true;try{if(!operatorAuth){operatorAuth={id:crypto.randomUUID(),token:randomToken()};save('rutasec-operator-access',operatorAuth);}await api('/api/operators',{body:{id:operatorAuth.id,name,whatsapp},token:operatorAuth.token});profileEditing=false;if($b('marketProfileForm')?.parentElement!==document.querySelector('.operator-section[data-section="profile"]'))document.querySelector('.operator-section[data-section="profile"]')?.appendChild($b('marketProfileForm'));operatorRenderKey='';await refreshOperator();$b('operatorProfileMessage').textContent='Operadora guardada. Este teléfono conserva el acceso a tu panel.';notify('Operadora lista para publicar viajes.');}catch(error){$b('operatorProfileMessage').textContent=error.message;}finally{button.disabled=false;}}
async function refreshOperator(){if(!operatorAuth)return;try{const data=await api('/api/operator',{token:operatorAuth.token});operatorData=data;lastOperatorError='';if(currentScreen()==='operator'){operatorSkeleton();if(!$b('marketOperatorName').value){$b('marketOperatorName').value=data.profile.name;$b('marketOperatorPhone').value=data.profile.whatsapp;}renderOperatorData();$b('operatorSyncState').textContent='● Sincronizado · las reservas llegan sin recargar';}}catch(error){lastOperatorError=error.message;if(currentScreen()==='operator')$b('operatorSyncState').textContent=error.message;}}
function renderOperatorData(){if(!operatorData)return;$b('operatorDashboard').hidden=false;if($b('operatorSubnav'))$b('operatorSubnav').hidden=false;$b('marketProfileForm').hidden=!profileEditing;$b('operatorProfileToggle').hidden=false;$b('operatorProfileToggle').textContent=operatorData.profile.name+' · Editar operadora y WhatsApp';$b('marketRideForm').hidden=!rideFormOpen&&operatorData.rides.length>0;const d=operatorData,key=JSON.stringify({revision:d.revision,rides:d.rides,bookings:d.bookings});if(key===operatorRenderKey)return;operatorRenderKey=key;const confirmed=d.bookings.filter(b=>b.status==='confirmed'&&!['finished','cancelled'].includes(b.ride.status)),gross=d.bookings.reduce((sum,b)=>sum+b.payment.amountCents,0),refunds=d.bookings.filter(b=>b.status==='cancelled').reduce((sum,b)=>sum+b.payment.amountCents,0);$b('operatorTotals').innerHTML='<div><small>Reservas activas</small><strong>'+confirmed.length+'</strong></div><div><small>Asientos reservados</small><strong>'+confirmed.reduce((sum,b)=>sum+b.seats,0)+'</strong></div><div><small>Ventas netas demo</small><strong>'+money(gross-refunds)+'</strong></div>';
 const rides=d.rides.filter(r=>operatorFilter==='all'||(operatorFilter==='upcoming'?r.status==='published'&&r.departsAt>=Date.now():r.status===operatorFilter));$b('operatorRideList').innerHTML=rides.length?rides.map(r=>{const count=d.bookings.filter(b=>b.rideId===r.id&&b.status==='confirmed').length;return '<article class="operator-ride"><span class="market-status '+(r.status==='cancelled'?'cancelled':'')+'">'+esc(statusText[r.status])+'</span><h3>'+esc(r.origin)+' → '+esc(r.destination)+'</h3><p>'+esc(r.date)+' · '+esc(r.time)+' · '+esc(r.vehicle)+'<br>'+money(r.priceCents)+' por asiento</p><strong class="capacity">'+r.available+' disponibles · '+r.occupied+' ocupados / '+r.capacity+'</strong><div class="seat-dots" aria-label="'+r.occupied+' asientos ocupados de '+r.capacity+'">'+Array.from({length:r.capacity},(_,i)=>'<i class="'+(i>=r.occupied?'free':'')+'"></i>').join('')+'</div><div class="market-controls"><button onclick="BookingApp.selectOperatorRide(\''+r.id+'\')">Ver reservas ('+count+')</button>'+(['published','draft'].includes(r.status)?'<button onclick="BookingApp.editRide(\''+r.id+'\')">Editar</button>':'')+(r.status==='draft'?'<button onclick="BookingApp.rideAction(\''+r.id+'\',\'publish\')">Publicar</button>':'')+(r.status==='published'?'<button onclick="BookingApp.copyRide(\''+r.id+'\')">Copiar enlace de salida</button><button '+(r.origin!=='Cuenca'||r.destination!=='Guayaquil'?'disabled':'')+' onclick="BookingApp.rideAction(\''+r.id+'\',\'start\')">Iniciar recorrido simulado</button>':'')+(r.liveId?'<button onclick="BookingApp.followOperator(\''+r.id+'\')">Ver recorrido</button>':'')+(r.status==='running'?'<button onclick="BookingApp.rideAction(\''+r.id+'\',\'finish\')">Finalizar viaje</button>':'')+(!['finished','cancelled'].includes(r.status)?'<button class="danger" onclick="BookingApp.rideAction(\''+r.id+'\',\'cancel\')">Cancelar viaje demo</button>':'')+'</div>'+(r.activeAlert?'<div class="operator-alert"><strong>SOS DE DEMOSTRACIÓN · '+(r.activeAlert.status==='attended'?'ATENDIDA':'ABIERTA')+'</strong><p>Alerta '+esc(r.activeAlert.id.slice(0,8))+' · '+r.activeAlert.position.lat.toFixed(5)+', '+r.activeAlert.position.lng.toFixed(5)+' · ubicación simulada</p>'+(r.activeAlert.status!=='attended'?'<button class="market-small" onclick="BookingApp.attendSOS(\''+r.id+'\')">Marcar SOS atendida</button>':'')+'</div>':'')+'</article>';}).join(''):'<p class="market-empty">No hay viajes en esta categoría.</p>';
 if(!operatorRideId&&d.rides.length)operatorRideId=d.rides.at(-1).id;renderReservations();$b('operatorSalesHistory').innerHTML='<p class="market-note">Ventas brutas: '+money(gross)+' · Reembolsos demo: '+money(refunds)+'</p>'+(d.bookings.length?d.bookings.toReversed().map(b=>'<div class="sales-entry"><strong>'+esc(b.id.slice(0,8).toUpperCase())+' · '+money(b.payment.amountCents)+'</strong><br>'+esc(b.itinerary.origin)+' → '+esc(b.itinerary.destination)+' · '+b.seats+' asiento(s)<br><small>'+esc(b.passengers.map(p=>p.name).join(', '))+' · '+(b.status==='cancelled'?'Cancelada · reembolso simulado':'Pago simulado confirmado')+'</small></div>').join(''):'<p class="market-note">Aún no hay ventas simuladas.</p>');
}
function renderReservations(){const r=operatorData?.rides.find(r=>r.id===operatorRideId);if(!r){$b('operatorReservations').innerHTML='<p class="market-note">Publica una salida para recibir reservas.</p>';return;}$b('operatorReservationsTitle').textContent='Reservas · '+r.origin+' → '+r.destination+' · '+r.time;const items=operatorData.bookings.filter(b=>b.rideId===r.id);$b('operatorReservations').innerHTML=items.length?items.map(b=>'<article class="operator-booking"><strong>Reserva '+esc(b.id.slice(0,8).toUpperCase())+' · '+b.seats+' asiento(s) · '+money(b.payment.amountCents)+'</strong><p>'+esc(b.id)+'<br>'+(b.status==='cancelled'?'Cancelada · reembolso simulado':'Pago SIMULADO CONFIRMADO · '+esc(payText[b.payment.method]))+'</p>'+b.passengers.map((p,i)=>'<div class="operator-passenger"><span>'+esc(p.name)+'</span>'+(p.boardedAt?'<span class="market-status">Abordó</span>':b.status==='confirmed'&&['published','running'].includes(r.status)?'<button class="market-small" onclick="BookingApp.board(\''+b.id+'\','+i+')">Marcar abordado</button>':'')+'</div>').join('')+(b.status==='confirmed'&&!['finished','cancelled'].includes(r.status)&&!b.passengers.some(p=>p.boardedAt)?'<button class="market-small danger" onclick="BookingApp.cancelBooking(\''+b.id+'\',true)">Cancelar reserva demo</button>':'')+'</article>').join(''):'<p class="market-note">Sin reservas todavía. Se mostrarán automáticamente cuando el pasajero confirme su pago simulado.</p>';}
function rideFields(){return {origin:$b('marketFrom').value,destination:$b('marketTo').value,date:$b('marketDate').value,time:$b('marketTime').value,vehicleType:$b('marketVehicleType').value,vehicle:$b('marketVehicle').value.trim(),capacity:Number($b('marketCapacity').value),priceCents:Math.round(Number($b('marketPrice').value)*100)}}
async function saveRide(){if(operatorBusy||!operatorAuth||!$b('marketRideForm').reportValidity())return;operatorBusy=true;$b('saveMarketRide').disabled=true;$b('rideFormError').textContent='';try{const fields=rideFields(),data=editingRide?await api('/api/rides/'+editingRide.id,{token:operatorAuth.token,body:{...fields,action:'update',expectedRevision:editingRide.revision}}):await api('/api/rides',{token:operatorAuth.token,body:{...fields,requestId:rideRequestId,publish:$b('marketPublish').checked}});operatorRideId=data.ride.id;cancelEdit();operatorRenderKey='';await refreshOperator();await loadCatalog();notify('Viaje guardado y sincronizado.');}catch(error){$b('rideFormError').textContent=error.message;}finally{operatorBusy=false;$b('saveMarketRide').disabled=false;}}
function editRide(id){const r=operatorData.rides.find(r=>r.id===id);if(!r)return;editingRide=r;rideFormOpen=true;$b('marketRideForm').hidden=false;for(const [key,value] of Object.entries({marketFrom:r.origin,marketTo:r.destination,marketDate:r.date,marketTime:r.time,marketVehicleType:r.vehicleType,marketVehicle:r.vehicle,marketCapacity:r.capacity,marketPrice:r.priceCents/100}))$b(key).value=value;$b('rideFormTitle').textContent='Editar viaje';$b('saveMarketRide').textContent='Guardar cambios';$b('marketPublishLabel').hidden=true;$b('cancelRideEdit').hidden=false;$b('rideFormError').textContent=r.occupied?'Con reservas puedes ajustar precio y capacidad; se conserva ruta, horario y vehículo.':'';$b('marketRideForm').scrollIntoView({behavior:'smooth',block:'start'});}
function cancelEdit(){editingRide=null;rideFormOpen=false;if(operatorData?.rides.length)$b('marketRideForm').hidden=true;rideRequestId=crypto.randomUUID();$b('rideFormTitle').textContent='Crear viaje';$b('saveMarketRide').textContent='Publicar viaje';$b('marketPublishLabel').hidden=false;$b('cancelRideEdit').hidden=true;$b('rideFormError').textContent='';}
async function rideAction(id,action){if(operatorBusy)return;if(action==='cancel'&&!window.confirm('¿Cancelar este viaje de demostración y reembolsar sus reservas simuladas?'))return;operatorBusy=true;try{await api('/api/rides/'+id,{token:operatorAuth.token,body:{action}});operatorRenderKey='';await refreshOperator();await loadCatalog();notify(action==='start'?'Recorrido iniciado. Los pasajeros ya pueden seguirlo.':'Viaje actualizado.');}catch(error){notify(error.message);}finally{operatorBusy=false;}}
async function bookingAction(id,body,asOperator){const token=asOperator?operatorAuth?.token:ticketKeys[id]||activeTicketToken;try{const data=await api('/api/bookings/'+id,{token,body});if(activeTicket?.id===id){activeTicket=data.booking;ticketRenderKey='';renderTicket();}operatorRenderKey='';if(operatorAuth&&currentScreen()==='operator')await refreshOperator();await loadCatalog();if(currentScreen()==='mytrip')await loadHistory();notify('Reserva actualizada y sincronizada.');}catch(error){notify(error.message);}}
async function cancelBooking(id,asOperator=false){if(!window.confirm('¿Cancelar esta reserva de demostración? Sus asientos volverán a estar disponibles y se registrará un reembolso simulado.'))return;await bookingAction(id,{action:'cancel'},asOperator);}
async function poll(){clearTimeout(pollTimer);if(polling)return;polling=true;try{if(!document.hidden){await loadCatalog();const screen=currentScreen();if(screen==='operator'&&operatorAuth)await refreshOperator();if(screen==='ticket'&&activeTicket)await loadTicket(activeTicket.id,activeTicketToken);if(screen==='mytrip')await loadHistory();}}finally{polling=false;pollTimer=setTimeout(poll,POLL_INTERVAL_MS);}}
async function routeBookingHash(){const hash=location.hash.slice(1),m=hash.match(/^(boleto|salida)\/([a-f0-9-]{36})(?:\?(.*))?$/);if(!m)return;const [,kind,id,query]=m;if(kind==='boleto'){show('ticket');activeTicket=null;ticketRenderKey='';await loadTicket(id,new URLSearchParams(query||'').get('key'));}else{await loadCatalog();const r=catalog.find(r=>r.id===id);if(!r)return notify('La salida no está publicada o ya no existe.');selectedRideId=id;show('detail');}const splash=$b('splash');if(splash){splash.style.display='none';splash.setAttribute('aria-hidden','true');}}
window.BookingApp={passengerFilter(value){passengerSort=value;renderResults();},companyFilter(value){passengerCompany=value;renderResults();},favoriteOperator:toggleOperatorFavorite,saveBrand,operatorSection:selectOperatorSection,openScanner:openBoardingScanner,closeScanner:closeBoardingScanner,validateQR:validateBoardingQR,newRide(){cancelEdit();rideFormOpen=true;$b('marketRideForm').hidden=false;$b('marketRideForm').scrollIntoView({behavior:'smooth',block:'start'});},editOperatorProfile(){profileEditing=!profileEditing;$b('marketProfileForm').hidden=!profileEditing;},renderResults,renderDetail,renderCheckout,pay,renderHistory,openOperator,saveOperator,saveRide,editRide,cancelEdit,rideAction,choose,allDepartures(){showAll=true;renderResults();},vehiclePreset(type){$b('marketVehicle').value=({van:'Mercedes Sprinter',minivan:'Hyundai H1',suv:'Kia Sorento',auto:'Toyota Corolla'})[type];},filterRides(value){operatorFilter=value;operatorRenderKey='';document.querySelectorAll('[data-operator-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.operatorFilter===value));renderOperatorData();},selectOperatorRide(id){operatorRideId=id;renderReservations();$b('operatorReservationsTitle').scrollIntoView({behavior:'smooth',block:'start'});},board(id,index){bookingAction(id,{action:'board',passengerIndex:index},true);},cancelBooking,cancelCurrent(){if(activeTicket)cancelBooking(activeTicket.id);},openTicket(id){const key=ticketKeys[id];if(!key)return;location.hash='boleto/'+id+'?key='+encodeURIComponent(key);},async shareCurrentTicket(){if(!activeTicket)return;try{await navigator.clipboard.writeText(ticketLink(activeTicket,activeTicketToken));notify('Enlace privado del boleto copiado.');}catch{notify('Puedes copiar la dirección del boleto desde el navegador.');}},async copyRide(id){try{await navigator.clipboard.writeText(rideLink(id));notify('Enlace público de salida copiado.');}catch{notify(rideLink(id));}},followTicket(){if(activeTicket?.status==='confirmed'&&activeTicket.ride.liveId)window.LiveTrip?.openLinked(activeTicket.ride.liveId,activeTicketToken);},followOperator(id){const r=operatorData?.rides.find(r=>r.id===id);if(r?.liveId)window.LiveTrip?.openLinked(r.liveId,operatorAuth.token);},async attendSOS(id){const r=operatorData?.rides.find(r=>r.id===id);if(!r?.liveId)return;try{const data=await api('/api/trips/'+r.liveId,{token:operatorAuth.token});await api('/api/trips/'+r.liveId+'/commands',{token:operatorAuth.token,body:{action:'attend',alertId:r.activeAlert.id,requestId:crypto.randomUUID(),expectedRevision:data.trip.revision}});operatorRenderKey='';await refreshOperator();}catch(error){notify(error.message);}}};
window.select=choose;window.cycle=n=>{if(!fleet.length)return;selected=(selected+n+fleet.length)%fleet.length;selectedRideId=fleet[selected].id;checkoutBuilt='';renderDetail();};
document.addEventListener('rutas:screen',event=>{if(event.detail==='results')loadCatalog();if(event.detail==='mytrip')loadHistory();});
window.addEventListener('hashchange',routeBookingHash);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});
if(currentScreen()==='operator')openOperator();if(currentScreen()==='mytrip'){renderHistory();loadHistory();}loadCatalog();routeBookingHash();poll();
